// Demo: replace with Stripe node or HTTP to billing API.
const base = 78000;
const day = Math.floor(Date.now() / 86400000);
const mrr = Math.round(base + (day % 90) * 120 + Math.sin(day / 7) * 400);
return [{ json: { metric: 'stripe.mrr', value: mrr, tags: { source: 'stripe', currency: 'usd' } } }];
